// === 配置 ===
const ALLOWED_USERS = [493325033];
const METAPI = 'https://metapi-krj9.onrender.com';

// Telegram Bot API 的 token 只能放在 URL 路径里，n8n 的 telegramApi 凭据
// 没法被 HTTP Request 节点复用（那个凭据没有 authenticate 段）。
// 所以这里读环境变量，读不到才用字面量兜底。
let BOT_TOKEN = '8680016700:AAE2DwDZQWiRl6nsr74YSD_n9PzDIc2FRGI';
try { if ($env.TELEGRAM_BOT_TOKEN) BOT_TOKEN = $env.TELEGRAM_BOT_TOKEN; } catch (e) { /* 环境变量被禁 */ }
const TG = 'https://api.telegram.org/bot' + BOT_TOKEN;

const out = (obj) => [{ json: { tgBase: TG, ...obj } }];

// 站点按钮的文字形如 "✅ seekai (8)" / "▫️ 咕咕嘎嘎公益站 (13)"
//
// ▫️ 是两个码位：U+25AB + 变体选择符 U+FE0F。只吃掉 U+25AB 的话，残留的
// U+FE0F 会粘在站点名前面（渲染上看不出来，但拼进 /probe 参数和复制出来的
// 命令里都是脏字符）。
const PREFIX = /^(?:\u2705|\u25AB)\uFE0F?\s*/;

/**
 * 从回传的键盘还原站点列表。
 *
 * 这是整个设计的关键：**键盘本身就是选中状态**。Telegram 在 callback_query
 * 里把原消息的 reply_markup 一并回传，所以点一下就能知道当前选了什么，
 * 不需要任何服务端存储。
 *
 * 为什么不用 $getWorkflowStaticData：n8n 的静态数据是「执行开始读一次快照、
 * 执行结束整对象 UPDATE 写回」，没有锁也没有字段级合并。快速连点几个站点时
 * 多个执行并发，后结束的会把先结束的整个覆盖掉（lost update），而且 n8n 重启
 * 就清空。键盘即状态则各画各的，不存在覆盖。
 *
 * 按钮文字是截断过的（每行 3 个，省屏幕高度），完整站点名在 callback_data 里。
 */
function parseSites(kb) {
  const sites = [];
  for (const row of kb) {
    for (const b of row || []) {
      const raw = String(b.callback_data || '');
      if (!raw.startsWith('t:')) continue;
      const on = String(b.text || '').startsWith('\u2705');
      // 格式 t:<id>[:<完整名>]，名字里可能有冒号，所以只切前两段
      const first = raw.indexOf(':');
      const second = raw.indexOf(':', first + 1);
      const id = Number(second === -1 ? raw.slice(2) : raw.slice(2, second));
      if (!Number.isInteger(id) || id <= 0) continue;
      const fullName = second === -1 ? '' : raw.slice(second + 1);
      const label = String(b.text || '').replace(PREFIX, '');
      sites.push({
        siteId: id,
        // 优先用 callback_data 里的全名；老键盘没有的话退回按钮文字
        siteName: fullName || label,
        label,
        on,
      });
    }
  }
  return sites;
}

const ev = $input.first().json;
const cb = ev.callback_query;

// ==================== 分支 A：按钮点击 ====================
if (cb) {
  const chatId = cb.message?.chat?.id;
  const userId = Number(cb.from?.id || 0);
  const messageId = cb.message?.message_id;
  const data = String(cb.data || '');
  const kb = cb.message?.reply_markup?.inline_keyboard;

  if (!ALLOWED_USERS.includes(userId)) {
    return out({ action: 'answer', callbackQueryId: cb.id, text: '❌ 未授权', chatId });
  }

  // 刷新：强制重拉站点列表。勾选从键盘带过去，按 id 保留。
  if (data === 'refresh') {
    return out({
      action: 'fetch',
      force: true,
      callbackQueryId: cb.id,
      chatId,
      messageId,
      sites: Array.isArray(kb) ? parseSites(kb) : [],
    });
  }

  if (data === 'noop') {
    return out({ action: 'answer', callbackQueryId: cb.id, text: '↑ 点站点名来勾选', chatId });
  }

  // 键盘没了就无从得知当前选了什么。Telegram 文档里 message 是 Optional，
  // 实践中一直在，但不能假设。用 alert 而不是 toast：这条提示需要被读到。
  if (!Array.isArray(kb)) {
    return out({
      action: 'answer',
      callbackQueryId: cb.id,
      chatId,
      text: '⚠️ 会话已过期，请重新发送 /targets',
      showAlert: true,
    });
  }

  const sites = parseSites(kb);
  if (!sites.length) {
    return out({
      action: 'answer',
      callbackQueryId: cb.id,
      chatId,
      text: '⚠️ 这条消息里没有站点，请重新发送 /targets',
      showAlert: true,
    });
  }

  const picked = sites.filter((s) => s.on);

  if (data === 'clr') {
    sites.forEach((s) => { s.on = false; });
    return out({ action: 'render', chatId, messageId, callbackQueryId: cb.id, sites, ackText: '🧹 已清空' });
  }

  if (data === 'run') {
    if (!picked.length) {
      return out({ action: 'answer', callbackQueryId: cb.id, text: '⚠️ 先点几个站点', chatId });
    }
    return out({ action: 'probe', chatId, siteIds: picked.map((s) => s.siteId), callbackQueryId: cb.id });
  }

  if (data.startsWith('t:')) {
    // callback_data 是 t:<id>[:<完整名>]。名字里可能有冒号，所以只切前两段——
    // 不能整个 data.slice(2) 去 Number()，那会得到 NaN，每个站点都匹配不上。
    const id = Number(data.slice(2).split(':')[0]);
    const target = sites.find((s) => s.siteId === id);
    if (!target) {
      return out({ action: 'answer', callbackQueryId: cb.id, text: '无效站点', chatId });
    }
    target.on = !target.on;
    const n = sites.filter((s) => s.on).length;
    return out({
      action: 'render',
      chatId,
      messageId,
      callbackQueryId: cb.id,
      sites,
      toggledId: id,
      ackText: (target.on ? '➕ ' : '➖ ') + target.siteName + ' · 已选 ' + n + ' 个',
    });
  }

  return out({ action: 'answer', callbackQueryId: cb.id, text: '未知操作', chatId });
}

// ==================== 分支 B：文字命令 ====================
const msg = ev.message || {};
const chatId = msg.chat?.id;
const userId = Number(msg.from?.id || 0);
const text = (msg.text || '').trim();
const parts = text.split(/\s+/);
const cmd = (parts[0] || '').replace(/^\//, '').toLowerCase();
const args = parts.slice(1).join(' ');

// action:'send' 由动作路由的 fallback 输出接走
const reply = (t) => out({ action: 'send', chatId, text: t });

if (!ALLOWED_USERS.includes(userId)) {
  return reply('❌ 未授权访问\n\n此机器人仅供管理员使用。\n您的 User ID: ' + userId);
}

if (!cmd || cmd === 'help' || cmd === 'start') {
  return reply('🤖 MetAPI 探测机器人\n\n/targets - 按钮勾选站点，直接探测\n/probe all - 探测所有站点\n/probe 180001,180002 - 探测指定站点\n/status - 查看最近一次探测结果\n/help - 显示帮助\n\n⚠️ 探测会消耗真实配额');
}

// /targets 走缓存（除非超过 10 分钟）：站点列表要实时探测所有站点，
// 每次都快不了。要看最新的就点面板上的「🔄 刷新」。
if (cmd === 'targets') {
  return out({ action: 'fetch', chatId, sites: [], notice: '点站点名勾选，选好后点「🚀 直接探测」' });
}

if (cmd === 'probe') {
  const raw = args.trim().toLowerCase();
  const siteIds = raw === 'all' || raw === '' ? 'all' : raw.split(/[^0-9]+/).filter(Boolean).map(Number).filter((n) => Number.isInteger(n) && n > 0);
  if (Array.isArray(siteIds) && siteIds.length === 0) {
    return reply('❌ 站点ID格式不对\n\n用法: /probe all 或 /probe 180001,180002');
  }
  return out({ action: 'probe', chatId, siteIds });
}

if (cmd === 'status') {
  // 不带参数 = 查最近一次；带参数 = 查指定任务
  const url = args.trim() ? METAPI + '/api/remote-probe/status/' + encodeURIComponent(args.trim()) : METAPI + '/api/remote-probe/status';
  return out({ action: 'api', chatId, method: 'GET', url });
}

return reply('❓ 未知命令: /' + cmd + '\n\n发送 /help 查看可用命令');

// 缓存判断。站点列表要实时探测所有站点（~1.3s 起，冷启动更久），
// /targets 每次都拉太慢，所以缓存下来长期复用；只有点面板上的
// 「🔄 刷新」才重拉。
//
// 为什么不设 TTL：站点集合变动很慢，按时间过期只会让用户白等一次冷启动，
// 却几乎不会带来更新的数据。面板上标着缓存时间，用户自己决定何时刷新。
//
// 缓存在静态数据里，只影响「列表内容」，不影响勾选状态——勾选在键盘上，
// 所以这里的并发覆盖风险只关乎列表新旧，不关乎用户操作，可以接受。
const ctx = $('预处理').first().json;
const store = $getWorkflowStaticData('global');
if (!store.sites) store.sites = {};
if (!store.cachedAt) store.cachedAt = {};

const key = String(ctx.chatId);
const cached = Array.isArray(store.sites[key]) && store.sites[key].length > 0;

if (cached && !ctx.force) {
  return [{ json: { ...ctx, action: 'render', cached: true, cachedAt: store.cachedAt[key], apiSites: store.sites[key] } }];
}

return [{ json: { ...ctx, action: 'need-api' } }];

// 把拉回来的列表写进缓存，再交给「渲染键盘」画出来
const ctx = $('缓存判断').first().json;
const data = $input.first().json || {};
const store = $getWorkflowStaticData('global');

const key = String(ctx.chatId);

if (data.error || data.success === false || !Array.isArray(data.sites) || !data.sites.length) {
  // 拉失败不动缓存：旧列表仍然可用，比一张空面板强
  return [{ json: {
    ...ctx,
    action: 'render',
    fetchFailed: data.error?.description || data.message || '没有可用站点',
    apiSites: store.sites[key] || [],
  } }];
}

store.sites[key] = data.sites.map((s) => ({ siteId: s.siteId, siteName: s.siteName, modelCount: s.modelCount || 0 }));
store.cachedAt[key] = Date.now();

return [{ json: { ...ctx, action: 'render', fetchFailed: null, apiSites: store.sites[key] } }];

// 画键盘。三条来源：
//   render + cached  —— 站点列表来自缓存（/targets 的常见路径）
//   render + apiSites —— 站点列表来自 API（首次、或点了刷新）
//   render（无列表）  —— 点击路径，列表来自回传的键盘本身（零 IO）
//
// 为什么不用 n8n 的 Telegram 节点：它的 inlineKeyboard 是 fixedCollection，
// 路由层按 node.parameters 的原始路径逐层回读子字段。一旦任何一层是表达式，
// 那条路径在原始参数里就不存在，整块键盘被静默丢掉——实测整对象表达式、
// 嵌套表达式都发不出键盘。动态站点列表只能走原生 API。
// 读直接上游，不写死节点名。三条上游都会把 ctx 原样带下来：
//   动作路由(点击) / 要调接口吗(缓存命中) / 缓存站点列表(刚拉完 API)
// 站点列表就在 ctx 里。之前写死 $('预处理') 只对点击路径成立——
// 走缓存或刷新时，预处理里根本没有 apiSites，于是每次都画成
// 「没有可用的站点」，点刷新也一样（刷新只是绕过了缓存，数据照样丢）。
const ctx = $input.first().json;

const tg = ctx.tgBase;
const chatId = ctx.chatId;
const messageId = ctx.messageId || null;

const apiSites = Array.isArray(ctx.apiSites) ? ctx.apiSites : null;

let sites;
let fetchFailed = ctx.fetchFailed || null;

if (apiSites) {
  // 刷新前已经勾上的，按 id 保留
  const wasOn = new Set((ctx.sites || []).filter((s) => s.on).map((s) => s.siteId));
  sites = apiSites.map((s) => ({
    siteId: s.siteId,
    siteName: s.siteName,
    on: wasOn.has(s.siteId),
  }));
} else {
  sites = Array.isArray(ctx.sites) ? ctx.sites : [];
}

// 一次 API 都没成功过、键盘也空——没有可画的
if (!sites.length) {
  const rows = [[{ text: '🔄 刷新', callback_data: 'refresh' }]];
  const text = (fetchFailed ? '⚠️ ' + fetchFailed + '\n\n' : '') + '没有可用的站点。';
  const emptyBody = { chat_id: chatId, text, reply_markup: { inline_keyboard: rows } };
  const emptyItems = [{ json: {
    url: tg + (messageId ? '/editMessageText' : '/sendMessage'),
    body: messageId ? { ...emptyBody, message_id: messageId } : emptyBody,
  } }];
  // 点「刷新」落到这条路径时同样要应答，否则按钮一直转圈
  if (ctx.callbackQueryId) emptyItems.push(ackItem(tg, ctx));
  return emptyItems;
}

// 每行 3 个：按钮行高是固定的，唯一能压高度的办法是减少行数。
// 代价是名字要截断，完整名字塞进 callback_data（上限 64 字节）。
const PER_ROW = 3;
const MAX_LABEL = 7;
const truncate = (s) => (s.length > MAX_LABEL ? s.slice(0, MAX_LABEL - 1) + '…' : s);

const rows = [];
for (let i = 0; i < sites.length; i += PER_ROW) {
  rows.push(sites.slice(i, i + PER_ROW).map((s) => ({
    text: (s.on ? '✅' : '▫️') + truncate(s.siteName),
    // t:<id>:<完整名>，供正文列出全名，也供下一轮解析
    callback_data: 't:' + s.siteId + ':' + s.siteName,
  })));
}

rows.push([
  { text: '🚀 直接探测', callback_data: 'run' },
  { text: '🔄 刷新', callback_data: 'refresh' },
  { text: '🧹 清空', callback_data: 'clr' },
]);

const picked = sites.filter((s) => s.on);

let text = '';
if (ctx.notice) text += ctx.notice + '\n\n';
if (fetchFailed) text += '⚠️ 站点列表刷新失败（' + fetchFailed + '）\n\n';
if (ctx.cached) text += '（缓存于 ' + timeOf(ctx.cachedAt) + '，点「🔄 刷新」重拉）\n\n';
text += '📋 共 ' + sites.length + ' 个站点\n\n';
text += picked.length
  ? '已选 ' + picked.length + ' 个：' + picked.map((s) => s.siteName).join('、') + '\n'
  : '还没有勾选站点\n';

const msgBody = { chat_id: chatId, text, reply_markup: { inline_keyboard: rows } };

const items = [{ json: {
  // 带 messageId = 点击路径，原地改；否则是新的一次 /targets，发新消息
  url: tg + (messageId ? '/editMessageText' : '/sendMessage'),
  body: messageId ? { ...msgBody, message_id: messageId } : msgBody,
} }];

// 点击路径必须回一次 answerCallbackQuery，否则按钮一直转圈
if (ctx.callbackQueryId) items.push(ackItem(tg, ctx));

return items;

function ackItem(tg, ctx) {
  return { json: {
    url: tg + '/answerCallbackQuery',
    body: { callback_query_id: ctx.callbackQueryId, text: String(ctx.ackText || '已更新').slice(0, 200) },
  } };
}

// 缓存时间：当天只显示时分，跨天补上日期。缓存长期有效，一份列表可能放很久，
// 只写「缓存于 09:31」会让人以为是今天早上。
// n8n 容器时区可能是 UTC，但这里只是给个相对感，不值得引入时区处理。
function timeOf(ms) {
  if (!ms) return '未知时间';
  const d = new Date(ms);
  const hm = String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
  const today = new Date();
  const sameDay = d.getFullYear() === today.getFullYear()
    && d.getMonth() === today.getMonth()
    && d.getDate() === today.getDate();
  if (sameDay) return hm;
  return (d.getMonth() + 1) + '月' + d.getDate() + '日 ' + hm;
}

// answerCallbackQuery 只接受短文本（≤200），且必须尽快回应，否则按钮一直转圈
const ctx = $('预处理').first().json;
return [{ json: {
  url: ctx.tgBase + '/answerCallbackQuery',
  body: {
    callback_query_id: ctx.callbackQueryId,
    text: String(ctx.text || '').slice(0, 200),
    // alert 是弹窗而非顶部提示：会话过期这类消息需要被真的读到
    ...(ctx.showAlert ? { show_alert: true } : {}),
  },
} }];

// 纯文本回复（帮助、未授权、参数格式错误）也走同一个 HTTP 节点，
// 省掉一个 n8n Telegram 节点。
const ctx = $('预处理').first().json;
return [{ json: {
  url: ctx.tgBase + '/sendMessage',
  body: { chat_id: ctx.chatId, text: ctx.text || '' },
} }];

// /probe 或 点了「直接探测」：先看有没有在跑，避免重复计费
const ctx = $('预处理').first().json;
const siteIds = (ctx.siteIds === 'all' || ctx.siteIds == null) ? 'all' : ctx.siteIds;
return [{ json: {
  chatId: ctx.chatId,
  callbackQueryId: ctx.callbackQueryId || null,
  siteIds,
} }];

// 在跑就劝退，没跑就真的发起探测
//
// 只读 探测前置检查（同一条分支上的上游），不要读别的分支的节点：
// n8n 里访问没执行过的节点会抛 "hasn't been executed"，整条执行直接失败。
const ctx = $('探测前置检查').first().json;
const data = $input.first().json || {};

if (data.running) {
  return [{ json: { ...ctx, stage: 'busy' } }];
}

return [{ json: { ...ctx, stage: 'run' } }];

// 探测结果 / 状态查询 / 忙碌提示 → 一条 HTML 富消息
//
// 用 sendRichMessage 而不是 parse_mode=HTML：后者不支持 <table>，只有
// rich_message 的 HTML 子集能渲染成真正的表格（实测 20 行表格可发）。
const start = $('预处理').first().json;
const chatId = start.chatId;
const tg = start.tgBase;

let payload = {};
for (const name of ['发起探测', '查询任务状态', '决定是否探测']) {
  try {
    const item = $(name).first();
    if (item) { payload = item.json; break; }
  } catch (e) { /* 该分支没走到 */ }
}

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const items = [];
const send = (html, fallback) => {
  items.push({ json: {
    kind: 'rich',
    url: tg + '/sendRichMessage',
    body: { chat_id: chatId, rich_message: { html } },
    // 兜底文本：富消息接口较新，万一客户端或 API 不吃，降级成等宽文本重发。
    // 探测花的是真钱，结果不能因为显示格式丢掉。
    fallback,
  } });
};

if (payload.stage === 'busy') {
  send('<b>⏳ 已有探测在进行中</b>\n用 /status 查看进度', '⏳ 已有探测在进行中\n用 /status 查看进度');
} else if (payload.status === 'running' || payload.status === 'pending') {
  const id = esc(payload.taskId);
  send('🚀 <b>探测已启动</b>\n\nTask ID: <code>' + id + '</code>\n\n/status — 最近一次结果\n/status <code>' + id + '</code> — 指定任务',
    '🚀 探测已启动\n\nTask ID: ' + payload.taskId + '\n\n/status — 最近一次结果\n/status ' + payload.taskId + ' — 指定任务');
} else if (payload.status === 'completed' || (payload.success === true && payload.summary)) {
  buildResult(payload);
} else if (payload.error || payload.success === false) {
  const msg = payload.error?.description || payload.message || '未知错误';
  send('❌ <b>失败</b>\n' + esc(msg), '❌ 失败: ' + msg);
} else {
  const raw = JSON.stringify(payload).slice(0, 300);
  send('❓ 没有拿到结果\n<code>' + esc(raw) + '</code>', '❓ 没有拿到结果: ' + raw);
}

// 点了「直接探测」要回一次 callback，否则按钮一直转圈。
// 放在最后：它不参与富消息的成败判断。
if (start.callbackQueryId) {
  items.push({ json: {
    kind: 'ack',
    url: tg + '/answerCallbackQuery',
    body: { callback_query_id: start.callbackQueryId, text: '已开始' },
  } });
}

return items;

function buildResult(data) {
  const sm = data.summary || {};
  const av = data.available || [];
  const head = '✅ <b>探测完成</b>'
    + (data.taskId ? ' <code>' + esc(String(data.taskId).slice(0, 8)) + '</code>' : '')
    + '\n总计 ' + (sm.totalProbed ?? 0)
    + '｜可用 ' + (sm.supported ?? 0)
    + '｜不可用 ' + (sm.unsupported ?? 0)
    + '｜不确定 ' + (sm.inconclusive ?? 0)
    + (sm.durationMs ? '\n耗时 ' + (sm.durationMs / 1000).toFixed(1) + 's' : '');

  if (!av.length) {
    send(head + '\n\n⚠️ 没有可用模型', stripTags(head) + '\n\n⚠️ 没有可用模型');
    return;
  }

  // 表格：站点 / 模型 / 延迟 / 余额。服务端已按 站点→模型 排好，不再重排。
  const rows = [['站点', '模型', '延迟', '余额']];
  av.forEach((m) => {
    rows.push([
      m.siteName || '',
      m.modelName || '',
      m.latencyMs == null ? '—' : m.latencyMs + 'ms',
      (m.balance === null || m.balance === undefined) ? '—' : '$' + m.balance,
    ]);
  });

  const html = head + '\n\n🟢 <b>可用模型 ' + av.length + ' 个</b>\n'
    + '<table>' + rows.map((r) => '<tr>' + r.map((c) => '<td>' + esc(c) + '</td>').join('') + '</tr>').join('') + '</table>';

  // 兜底：等宽文本表格，列宽按显示宽度取最大值（中日韩字符占两列）
  const w = rows[0].map((_, i) => Math.max(...rows.map((r) => displayWidth(r[i]))));
  const pad = (s, n) => s + ' '.repeat(Math.max(0, n - displayWidth(s)));
  const pre = rows.map((r) => r.map((c, i) => pad(c, w[i])).join('  ').replace(/\s+$/, '')).join('\n');

  send(html, stripTags(head) + '\n\n可用模型 ' + av.length + ' 个\n<pre>' + pre + '</pre>');
}

function displayWidth(s) {
  let n = 0;
  for (const ch of String(s)) {
    const c = ch.codePointAt(0);
    n += (c >= 0x1100 && (c <= 0x115f || (c >= 0x2e80 && c <= 0xa4cf) || (c >= 0xac00 && c <= 0xd7a3)
      || (c >= 0xf900 && c <= 0xfaff) || (c >= 0xfe30 && c <= 0xfe6f) || (c >= 0xff00 && c <= 0xff60)
      || (c >= 0xffe0 && c <= 0xffe6))) ? 2 : 1;
  }
  return n;
}

function stripTags(s) {
  return String(s).replace(/<[^>]+>/g, '');
}

// 富消息没发出去 → 用等宽文本兜底重发，结果不能丢。
//
// 判断放在这里、而不是在 HTTP 之后用 IF 节点：HTTP Request 的输出会**替换**
// 输入，所以它之后 $json 里已经没有 kind 了，IF 判断恒为假、兜底每次都触发
// ——这正是「直接探测返回两条内容相似的消息」的原因。
//
// $input.first() 是本节点收到的、来自「格式化结果」的 item（还没被 HTTP 覆盖）。
const rich = $input.first().json || {};
if (rich.kind !== 'rich') return [];

const sent = $('发送富消息').first().json || {};
if (sent.ok === true) return [];

return [{ json: {
  url: $('预处理').first().json.tgBase + '/sendMessage',
  body: {
    chat_id: $('预处理').first().json.chatId,
    text: rich.fallback || '（没有可发送的内容）',
    parse_mode: 'HTML',
  },
} }];
